record_types.code:
type Configuration is
   record
      Name            : unbounded_String;
      Partitions      : partition_Vectors.Vector;
      name_Server     : name_server_Kind         := NS_Default;
      Starter         : starter_Kind             := st_Ada;
      boot_Protocol   : unbounded_String;
      boot_Location   : unbounded_String;
      Directory       : unbounded_String;
      version_Check   : Boolean                  := True;
      priority_Policy : priority_policy_Kind     := pol_Default;
   end record;

type partition_Rec is
   record
      Name           : unbounded_String;
      Units          : str_Vectors.Vector;
      Main           : unbounded_String;
      Termination    : termination_Kind   := term_Default;
      Reconnection   : reconnection_Kind  := recon_Default;
      Host           : unbounded_String;
      Directory      : unbounded_String;
      Priority       : Integer            := -1;
      task_pool_Max  : Integer            := -1;
      Restart        : restart_Kind       := R_None;
      restart_Max    : Integer            := 3;
      restart_Within : Float              := 60.0;
      restart_Then   : restart_then_Kind  := T_Quarantine;
   end record;
